<?php
declare(strict_types=1);
require_once __DIR__.'/lib/helpers.php';require_once __DIR__.'/lib/admin.php';require_once __DIR__.'/lib/notifications.php';
send_cors_headers();$principal=require_principal(['customer','vendor','admin','influencer']);$db=get_db();$method=$_SERVER['REQUEST_METHOD']??'GET';$isAdmin=$principal['type']==='admin';if($isAdmin)require_permission('support.manage',['admin']);
if($method==='GET'){$id=trim((string)($_GET['id']??''));$scope=$isAdmin?'1=1':'opened_by_type=:type AND opened_by_id=:owner';$params=$isAdmin?[]:['type'=>$principal['type'],'owner'=>$principal['id']];if($id!==''){$stmt=$db->prepare("SELECT * FROM support_tickets WHERE id=:id AND ({$scope})");$stmt->execute(['id'=>$id]+$params);$ticket=$stmt->fetch();if(!$ticket)json_response(404,['success'=>false,'message'=>'Support ticket not found.']);$messages=$db->prepare('SELECT id,sender_type,sender_id,message,created_at FROM support_messages WHERE ticket_id=:ticket AND (is_internal=0 OR :admin=1) ORDER BY created_at');$messages->execute(['ticket'=>$id,'admin'=>$isAdmin?1:0]);$ticket['messages']=$messages->fetchAll();json_response(200,['success'=>true,'ticket'=>$ticket]);}$stmt=$db->prepare("SELECT * FROM support_tickets WHERE {$scope} ORDER BY FIELD(status,'open','waiting_customer','waiting_vendor','resolved','closed'),created_at DESC LIMIT 200");$stmt->execute($params);json_response(200,['success'=>true,'tickets'=>$stmt->fetchAll()]);}
if($method==='POST'){$body=get_json_body();$ticketId=trim((string)($body['ticket_id']??''));$message=trim((string)($body['message']??''));if(mb_strlen($message)<10||mb_strlen($message)>5000)json_response(422,['success'=>false,'message'=>'Message must be between 10 and 5000 characters.']);if($ticketId===''){$subject=trim((string)($body['subject']??''));$category=trim((string)($body['category']??''));if(mb_strlen($subject)<5||mb_strlen($subject)>180||$category==='')json_response(422,['success'=>false,'message'=>'Subject and category are required.']);$ticketId=uuid_string();$number='SUP-'.gmdate('ymd').'-'.strtoupper(substr(bin2hex(random_bytes(3)),0,6));$priority=in_array($body['priority']??'normal',['low','normal','high','urgent'],true)?$body['priority']:'normal';$db->beginTransaction();try{$db->prepare('INSERT INTO support_tickets (id,ticket_number,opened_by_type,opened_by_id,order_id,vendor_id,category,subject,priority,status,first_response_due_at,resolution_due_at,created_at,updated_at) VALUES (:id,:number,:type,:owner,:order,:vendor,:category,:subject,:priority,"open",DATE_ADD(UTC_TIMESTAMP(),INTERVAL 8 HOUR),DATE_ADD(UTC_TIMESTAMP(),INTERVAL 3 DAY),UTC_TIMESTAMP(),UTC_TIMESTAMP())')->execute(['id'=>$ticketId,'number'=>$number,'type'=>$principal['type'],'owner'=>$principal['id'],'order'=>isset($body['order_id'])?(int)$body['order_id']:null,'vendor'=>$body['vendor_id']??null,'category'=>$category,'subject'=>$subject,'priority'=>$priority]);$db->prepare('INSERT INTO support_messages (id,ticket_id,sender_type,sender_id,message,is_internal,created_at) VALUES (:id,:ticket,:type,:owner,:message,0,UTC_TIMESTAMP())')->execute(['id'=>uuid_string(),'ticket'=>$ticketId,'type'=>$principal['type'],'owner'=>$principal['id'],'message'=>$message]);audit_event('support.ticket_opened','support_ticket',$ticketId,['category'=>$category,'priority'=>$priority]);$db->commit();json_response(201,['success'=>true,'message'=>'Support ticket created.','ticket_id'=>$ticketId,'ticket_number'=>$number]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}$scope=$isAdmin?'1=1':'opened_by_type=:type AND opened_by_id=:owner';$params=['id'=>$ticketId]+($isAdmin?[]:['type'=>$principal['type'],'owner'=>$principal['id']]);$stmt=$db->prepare("SELECT * FROM support_tickets WHERE id=:id AND ({$scope})");$stmt->execute($params);$ticket=$stmt->fetch();if(!$ticket)json_response(404,['success'=>false,'message'=>'Support ticket not found.']);$internal=$isAdmin&&!empty($body['is_internal'])?1:0;$db->prepare('INSERT INTO support_messages (id,ticket_id,sender_type,sender_id,message,is_internal,created_at) VALUES (:id,:ticket,:type,:owner,:message,:internal,UTC_TIMESTAMP())')->execute(['id'=>uuid_string(),'ticket'=>$ticketId,'type'=>$principal['type'],'owner'=>$principal['id'],'message'=>$message,'internal'=>$internal]);$db->prepare('UPDATE support_tickets SET status=:status,updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['status'=>$isAdmin?'waiting_customer':'open','id'=>$ticketId]);if(!$internal&&!$isAdmin&&$ticket['assigned_admin_id'])create_notification('admin',$ticket['assigned_admin_id'],'support_reply','Support ticket reply',"{$ticket['ticket_number']} received a reply.",'../support.php',['ticket_id'=>$ticketId]);json_response(201,['success'=>true,'message'=>'Reply added.']);}
if($method==='PATCH'&&$isAdmin){$body=get_json_body();$id=trim((string)($body['ticket_id']??''));$status=trim((string)($body['status']??''));if(!in_array($status,['open','waiting_customer','waiting_vendor','resolved','closed'],true))json_response(422,['success'=>false,'message'=>'Invalid ticket status.']);$db->prepare('UPDATE support_tickets SET status=:status,priority=COALESCE(:priority,priority),assigned_admin_id=COALESCE(:admin,assigned_admin_id),closed_at=IF(:status="closed",UTC_TIMESTAMP(),closed_at),updated_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['status'=>$status,'priority'=>in_array($body['priority']??'',['low','normal','high','urgent'],true)?$body['priority']:null,'admin'=>$body['assigned_admin_id']??$principal['id'],'id'=>$id]);audit_event('admin.support_ticket_updated','support_ticket',$id,['status'=>$status]);json_response(200,['success'=>true,'message'=>'Support ticket updated.']);}json_response(405,['success'=>false,'message'=>'Method not allowed.']);
